<?php

namespace Database\Factories;

use App\Models\Currency;
use App\Models\Invoice;
use App\Models\InvoiceNumberSequence;
use App\Models\InvoiceRecurrence;
use App\Models\InvoiceStatus;
use App\Models\Issuer;
use App\Models\Locale;
use App\Models\Payer;
use App\Models\Workspace;
use Database\Factories\Concerns\ResolvesLookups;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Invoice>
 */
class InvoiceFactory extends Factory
{
    use ResolvesLookups;

    /**
     * A draft generated by a new recurrence for the current month, issued
     * today and due in 10 days. The amount, texts, payer and issuer come from
     * the recurrence (or new records for a one-off) and are snapshotted. It
     * is in its recurrence's workspace; a one-off in the household one unless
     * told another, with a payer and issuer of it. The number is taken from
     * the workspace's `invoice_number_sequences`, as the real numbering does,
     * so it never collides with other invoices.
     *
     * A `workspace_id` given without a recurrence makes the new recurrence in
     * that workspace too.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'invoice_recurrence_id' => fn (array $attributes) => InvoiceRecurrence::factory()->state(
                self::givenWorkspaceId($attributes) === null ? [] : ['workspace_id' => self::givenWorkspaceId($attributes)],
            ),
            'workspace_id' => fn (array $attributes): int => self::recurrence($attributes)->workspace_id ?? WorkspaceFactory::household()->id,
            'period_key' => fn (array $attributes) => $attributes['invoice_recurrence_id'] === null ? null : now()->format('Y-m'),
            'number_year_month' => now()->format('Ym'),
            'number_sequence' => fn (array $attributes): int => self::nextSequence($attributes['workspace_id'], $attributes['number_year_month']),
            'number' => fn (array $attributes): string => sprintf('%s-%03d', $attributes['number_year_month'], $attributes['number_sequence']),
            'invoice_status_id' => fn (): int => static::lookupId(InvoiceStatus::class, InvoiceStatus::DRAFT),
            'issue_date' => now()->toDateString(),
            'due_date' => now()->addDays(10)->toDateString(),
            'currency_id' => fn (array $attributes): int => self::recurrence($attributes)->currency_id
                ?? static::lookupId(Currency::class, Currency::USD, ['name' => 'American dollar', 'symbol' => '$']),
            'amount' => fn (array $attributes) => self::recurrence($attributes)->amount ?? fake()->randomFloat(2, 100, 10000),
            'service_description' => fn (array $attributes) => self::recurrence($attributes)->service_description ?? fake()->sentence(),
            'email_subject' => fn (array $attributes) => self::recurrence($attributes)->email_subject ?? 'Invoice {% invoice.number %}',
            'email_body' => fn (array $attributes) => self::recurrence($attributes)->email_body ?? 'Please find the invoice attached.',
            'payer_id' => fn (array $attributes) => self::recurrence($attributes)->payer_id ?? Payer::factory()->state(['workspace_id' => $attributes['workspace_id']]),
            'payer_name' => fn (array $attributes) => self::payer($attributes)->name,
            'payer_address' => fn (array $attributes) => self::payer($attributes)->address,
            'issuer_id' => fn (array $attributes) => self::recurrence($attributes)->issuer_id ?? Issuer::factory()->state(['workspace_id' => $attributes['workspace_id']]),
            'issuer_name' => fn (array $attributes) => self::issuer($attributes)->name,
            'issuer_email' => fn (array $attributes) => self::issuer($attributes)->email,
            'issuer_postal_code' => fn (array $attributes) => self::issuer($attributes)->postal_code,
            'issuer_street' => fn (array $attributes) => self::issuer($attributes)->street,
            'issuer_district' => fn (array $attributes) => self::issuer($attributes)->district,
            'issuer_city' => fn (array $attributes) => self::issuer($attributes)->city,
            'issuer_state' => fn (array $attributes) => self::issuer($attributes)->state,
            'locale_id' => fn (array $attributes): int => self::recurrence($attributes)->locale_id
                ?? static::lookupId(Locale::class, Locale::EN, ['name' => 'English']),
            'pdf_path' => null,
            'sent_at' => null,
            'approved_by_id' => null,
            'created_by_id' => null,
        ];
    }

    /**
     * Waiting for approval (US-6.6).
     */
    public function pendingReview(): static
    {
        return $this->status(InvoiceStatus::PENDING_REVIEW);
    }

    /**
     * E-mailed, with its PDF.
     */
    public function sent(): static
    {
        return $this->status(InvoiceStatus::SENT, [
            'pdf_path' => fn (array $attributes): string => self::pdfPath($attributes),
            'sent_at' => now(),
        ]);
    }

    /**
     * The e-mail could not be sent.
     */
    public function failed(): static
    {
        return $this->status(InvoiceStatus::FAILED, [
            'pdf_path' => fn (array $attributes): string => self::pdfPath($attributes),
        ]);
    }

    /**
     * Cancelled; its number is never reused.
     */
    public function cancelled(): static
    {
        return $this->status(InvoiceStatus::CANCELLED);
    }

    /**
     * Sent once, without a recurrence (US-6.7).
     */
    public function oneOff(): static
    {
        return $this->state(fn (array $attributes) => [
            'invoice_recurrence_id' => null,
            'period_key' => null,
        ]);
    }

    /**
     * @param  array<string, mixed>  $attributes
     */
    private function status(string $slug, array $attributes = []): static
    {
        return $this->state(fn (array $current) => [
            'invoice_status_id' => static::lookupId(InvoiceStatus::class, $slug),
            ...$attributes,
        ]);
    }

    /**
     * Takes the next number of the workspace's month from its sequence row.
     */
    private static function nextSequence(int $workspaceId, string $yearMonth): int
    {
        $sequence = InvoiceNumberSequence::query()->firstOrCreate(
            ['workspace_id' => $workspaceId, 'year_month' => $yearMonth],
            ['last_number' => 0],
        );
        $sequence->increment('last_number');

        return $sequence->last_number;
    }

    /**
     * The workspace given to the factory (an id or a Workspace), before the
     * default runs; null when none was.
     *
     * @param  array<string, mixed>  $attributes
     */
    private static function givenWorkspaceId(array $attributes): ?int
    {
        $workspace = $attributes['workspace_id'] ?? null;

        return match (true) {
            is_int($workspace) => $workspace,
            $workspace instanceof Workspace => $workspace->id,
            default => null,
        };
    }

    /**
     * The stored PDF's path, as `InvoicePdf::path()` builds it.
     *
     * @param  array<string, mixed>  $attributes
     */
    private static function pdfPath(array $attributes): string
    {
        $workspace = Workspace::query()->findOrFail(self::givenWorkspaceId($attributes));

        return "invoices/{$workspace->friendly_id}/{$attributes['number']}.pdf";
    }

    /**
     * The recurrence the invoice is generated by; null for a one-off.
     *
     * @param  array<string, mixed>  $attributes
     */
    private static function recurrence(array $attributes): ?InvoiceRecurrence
    {
        if ($attributes['invoice_recurrence_id'] === null) {
            return null;
        }

        return InvoiceRecurrence::query()->withTrashed()->whereKey($attributes['invoice_recurrence_id'])->firstOrFail();
    }

    /**
     * @param  array<string, mixed>  $attributes
     */
    private static function payer(array $attributes): Payer
    {
        return Payer::query()->withTrashed()->whereKey($attributes['payer_id'])->firstOrFail();
    }

    /**
     * @param  array<string, mixed>  $attributes
     */
    private static function issuer(array $attributes): Issuer
    {
        return Issuer::query()->withTrashed()->whereKey($attributes['issuer_id'])->firstOrFail();
    }
}
